vector<int> BIT;
int N;

// Add 'val' to index 'i' (1-based indexing)
void update(int i, int val) {
    for (; i <= N; i += (i & -i)) {
        BIT[i] += val;
    }
}

// Get sum of array[1...i]
int query(int i) {
    int sum = 0;
    for (; i > 0; i -= (i & -i)) {
        sum += BIT[i];
    }
    return sum;
}

// Get sum of array[l...r]
int query(int l, int r) {
    return query(r) - query(l - 1);
}
